PAYLOAD = {'docs/PHASE_7_DESIGN.md': {'before': '34258e4c6ce2c1a08f9568a3039275f64f4009a2df8fac7c00e0b6c1f65a7611', 'after': ''}, 'docs/CLOUDPATH_TECHNICAL_DEBT.md': {'before': '1a9b80417c97cf5a79115f2e774e9048c4248d1f02af3349063751f4ce121953', 'after': ''}, 'backend/aws/s3_authorization_evidence.py': {'before': None, 'after': ''}, 'scripts/inspect_s3_authorization.py': {'before': None, 'after': ''}, 'tests/test_aws_s3_authorization_evidence.py': {'before': None, 'after': ''}, 'samples/aws/phase7_demo/s3_authz_allow.json': {'before': None, 'after': ''}, 'samples/aws/phase7_demo/s3_authz_bucket_deny.json': {'before': None, 'after': ''}, 'samples/aws/phase7_demo/s3_authz_endpoint_implicit.json': {'before': None, 'after': ''}, 'samples/aws/phase7_demo/s3_authz_identity_implicit.json': {'before': None, 'after': ''}, 'samples/aws/phase7_demo/s3_authz_missing_context.json': {'before': None, 'after': ''}, 'samples/aws/phase7_demo/s3_authz_resource_allow.json': {'before': None, 'after': ''}, 'samples/aws/phase7_demo/s3_authz_unknown.json': {'before': None, 'after': ''}}

BASELINE_COMMIT = "decb08a"

def run(args):
    return subprocess.check_output(args, text=True).strip()

def require(condition, message):
    if not condition: raise RuntimeError(message)

def checked_path(root, name):
    p = root / name
    require(not any(q.is_symlink() for q in (p, *p.parents) if q == p or root in q.parents), f'Symlink not permitted: {name}')
    return p

def verify(root):
    for name, digest in EXPECTED.items():
        p = checked_path(root, name)
        require(p.is_file() and hashlib.sha256(p.read_bytes()).hexdigest() == digest, f'Previous unit file mismatch: {name}')
    for name, item in PAYLOAD.items():
        p = checked_path(root, name)
        if item['before'] is None:
            require(not p.exists(), f'New path already exists: {name}')
    # Git commits may add files outside the original fingerprint manifest.
    # Permit those only when they belong to a committed successor of 7-C2
    # and are unchanged in both index and working tree.
    tracked = set(subprocess.check_output(['git','ls-files','-z'], text=True).split('\0')) - {''}
    extra = sorted(tracked - EXPECTED.keys())
    if extra:
        baseline = subprocess.run(['git','rev-parse','--verify',BASELINE_COMMIT+'^{commit}'], capture_output=True, text=True)
        require(baseline.returncode == 0 and subprocess.run(['git','merge-base','--is-ancestor',BASELINE_COMMIT,'HEAD']).returncode == 0,
                'Additional tracked files require a descendant of accepted 7-C2 commit '+BASELINE_COMMIT+': '+repr(extra))
        committed = set(subprocess.check_output(['git','ls-tree','-r','--name-only','-z','HEAD'], text=True).split('\0')) - {''}
        require(set(extra).issubset(committed), 'Unexpected newly staged files: '+repr(sorted(set(extra)-committed)))
        # Reject index flags that can conceal worktree changes for extra files.
        flags = subprocess.check_output(['git','--literal-pathspecs','ls-files','-v','-z','--',*extra],text=True).split('\0')
        require(all(not entry or entry.startswith('H ') for entry in flags), 'Additional tracked files have unsupported index flags; review before applying.')
        for args in (['--cached','HEAD'], []):
            rc = subprocess.run(['git','--literal-pathspecs','diff','--quiet','--no-ext-diff',*args,'--',*extra]).returncode
            require(rc == 0, 'Additional tracked files changed; review before applying: '+repr(extra))

def tests(expected):
    p = subprocess.run([sys.executable, '-m', 'pytest', '-q'], stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
    print(p.stdout, end='', flush=True)
    require(p.returncode == 0 and re.search(r'\b'+str(expected)+r' passed\b',p.stdout), f'Expected {expected} passed and exit code zero.')

def main():
    root = Path.cwd().resolve()
    require(len(sys.argv)==1, 'Run without arguments.')
    require(Path(run(['git','rev-parse','--show-toplevel'])).resolve()==root, 'Run from project root.')
    # Exact file fingerprints allow either the previous HEAD or its committed successor.
    require(sys.prefix!=sys.base_prefix, 'Activate project .venv.')
    verify(root)
    print('[1/4] Previous unit regression (1813 expected)', flush=True)
    tests(1813)
    verify(root)
    backup = Path(tempfile.mkdtemp(prefix='cloudpath-phase7g1-s3-authz-backup-',dir=root.parent))
    for name,item in PAYLOAD.items():
        if item['before'] is not None:
            p=backup/name; p.parent.mkdir(parents=True,exist_ok=True); shutil.copy2(root/name,p)
    (backup/'new-files.json').write_text(json.dumps([n for n,x in PAYLOAD.items() if x['before'] is None]))
    print('[2/4] Backup:',backup,flush=True)
    changed=[]
    try:
        for name,item in PAYLOAD.items():
            p=checked_path(root,name); changed.append(name); p.parent.mkdir(parents=True,exist_ok=True); p.write_bytes(base64.b64decode(item['after'],validate=True))
        print('[3/4] Applied offline S3 authorization constraints; existing network engines unchanged.',flush=True)
        print('[4/4] Full regression (1869 expected)',flush=True)
        tests(1869)
    except BaseException:
        print('[ROLLBACK] Restoring only this unit from:',backup,flush=True)
        for name in reversed(changed):
            if PAYLOAD[name]['before'] is None: (root/name).unlink(missing_ok=True)
            else: shutil.copy2(backup/name,root/name)
        raise
    print('[OK] Phase 7-G1 S3 authorization constraints applied; 1869 tests passed.',flush=True)
    print('[INFO] No Git commit, AWS API call or packet transmission; actual identity and policy attachment, network correlation, boundary/session/organizations, cross-account, KMS/ACL, web diagnostics and real AWS validation pending.',flush=True)
    print('[INFO] Backup retained:',backup,flush=True)

try:
    main()
except (Exception, KeyboardInterrupt) as exc:
    print('[ERROR]',exc,file=sys.stderr); sys.exit(1)
